// Purpose: Freeze a small, deterministic provider-read window for this manual proof.
const runUpperBound = new Date();
const windowStart = new Date(runUpperBound.getTime() - (7 * 24 * 60 * 60 * 1000));
return [{
    json: {
        contract_version: 'MICROSOFT_OAUTH_REFRESH_PROOF_V1',
        outlook_folder_id: 'inbox',
        outlook_window_start: windowStart.toISOString(),
        outlook_window_end: runUpperBound.toISOString(),
        outlook_server_filter: 'isDraft eq false',
        outlook_max_messages: 1,
        onedrive_folder_id: 'root',
        receipt_mode: 'REDACTED',
    },
}];

// Purpose: Discard all message fields before the OneDrive proof runs.
const contract = $('Freeze Bounded Probe').first().json;
if (contract.contract_version !== 'MICROSOFT_OAUTH_REFRESH_PROOF_V1'
    || contract.outlook_folder_id !== 'inbox'
    || contract.outlook_server_filter !== 'isDraft eq false'
    || contract.outlook_max_messages !== 1
    || contract.onedrive_folder_id !== 'root'
    || contract.receipt_mode !== 'REDACTED') {
    throw new Error('MICROSOFT_OAUTH_PROBE_CONTRACT_MISMATCH');
}
const rows = $input.all().map(item => item.json).filter(row => row && row.id);
if (rows.length > contract.outlook_max_messages) {
    throw new Error(`MICROSOFT_OAUTH_OUTLOOK_BOUND_EXCEEDED:${rows.length}`);
}
return [{
    json: {
        outlook_read_succeeded: true,
        outlook_items_observed: rows.length,
        outlook_max_messages: contract.outlook_max_messages,
        outlook_server_filter_applied: true,
        outlook_window_start: contract.outlook_window_start,
        outlook_window_end: contract.outlook_window_end,
    },
}];
